using System.Text.Json;
using QiuYaTools.Windows;

var cases = new List<object>();
var errors = new List<string>();
void Test(string name, Action run) { try { run(); cases.Add(new { name, passed = true }); } catch (Exception error) { cases.Add(new { name, passed = false, error = error.GetType().Name, code = error is NativeFailure failure ? failure.Code : null }); errors.Add(name); } }
void Assert(bool value) { if (!value) throw new InvalidOperationException("Assertion failed"); }
void Reject(Action action, string? code = null) { try { action(); } catch (NativeFailure failure) { if (code != null && failure.Code != code) throw new InvalidOperationException("Unexpected failure code " + failure.Code); return; } throw new InvalidOperationException("Expected rejection"); }
var image = new string('a', 64); var desktop = new string('b', 64); var actionDigest = new string('c', 64); var geometry = new string('d', 64);
var a = new ForegroundWorkerIdentity(200, "638000000000000001", @"C:\QiuYa\qiuya-windows.exe", image, 100, "638000000000000000", 1, desktop, new string('1', 32), "arm64");
var b = a with { Pid = 300, CreatedAtTicks = "638000000000000002", InstanceId = new string('2', 32) };
var target = "window:abcdef:400:638000000000000003";
// Each test owns its injected monotonic clock and state. No process/desktop/input API exists in this program.
ForegroundHandoffCore Core(ForegroundWorkerIdentity? identity = null) => new(identity ?? a, () => 100, 1000);
ForegroundReleaseToken Release(ForegroundHandoffCore core, long epoch = 1) { core.Refresh(0, true, true); core.BeforeLease(epoch); core.Consume(null, epoch, target, geometry, actionDigest); core.ActionSucceeded(epoch, target); return core.CleanRelease(epoch, true) ?? throw new InvalidOperationException("Missing release token"); }
ForegroundActionTicket Prepare(ForegroundHandoffCore core, long epoch = 1) { core.Refresh(0, true, true); return core.Prepare(epoch, 3, target, geometry, actionDigest, 5); }
Test("valid A release grants exact sibling once and B consumes original action once", () => {
    var donor = Core(); var receiver = Core(b); var release = Release(donor); var ticket = Prepare(receiver); var validations = 0; var calls = 0;
    var receipt = donor.Grant(release, b, ticket, () => validations++, pid => { Assert(pid == b.Pid); calls++; return (true, 0); });
    Assert(receipt.Attempted && receipt.Allowed && receipt.Error == 0 && receipt.Donor == a && receipt.Recipient == b && receipt.TicketId == ticket.TicketId && receipt.ReleaseTokenId == release.TokenId);
    receiver.BeforeLease(1); receiver.Consume(ticket, 1, target, geometry, actionDigest); Reject(() => receiver.Consume(ticket, 1, target, geometry, actionDigest), "foreground-ticket-invalid");
    Reject(() => donor.Grant(release, b, ticket, () => validations++, _ => { calls++; return (true, 0); }), "foreground-release-invalid"); Assert(validations == 1 && calls == 1);
});
Test("ASFW BOOL false is returned once and cannot be retried", () => { var core = Core(); var token = Release(core); var ticket = Prepare(Core(b)); var count = 0; var receipt = core.Grant(token, b, ticket, () => { }, _ => { count++; return (false, 5); }); Assert(receipt.Attempted && !receipt.Allowed && receipt.Error == 5); Reject(() => core.Grant(token, b, ticket, () => { }, _ => { count++; return (true, 0); })); Assert(count == 1); });
Test("ASFW exception consumes release before call and never retries", () => { var core = Core(); var token = Release(core); var ticket = Prepare(Core(b)); var count = 0; try { core.Grant(token, b, ticket, () => { }, _ => { count++; throw new InvalidOperationException("Injected API failure"); }); } catch (InvalidOperationException) { } Reject(() => core.Grant(token, b, ticket, () => { }, _ => { count++; return (true, 0); })); Assert(count == 1); });
Test("OS pin validation failure consumes release and calls no ASFW", () => { var core = Core(); var token = Release(core); var ticket = Prepare(Core(b)); var count = 0; Reject(() => core.Grant(token, b, ticket, () => throw new NativeFailure("test-pin", "Injected pin mismatch"), _ => { count++; return (true, 0); }), "test-pin"); Reject(() => core.Grant(token, b, ticket, () => { }, _ => { count++; return (true, 0); })); Assert(count == 0); });
Test("same worker is never granted ASFW", () => { var core = Core(); var release = Release(core); var ticket = Prepare(Core()); var calls = 0; Reject(() => core.Grant(release, a, ticket, () => { }, _ => { calls++; return (true, 0); }), "foreground-recipient-mismatch"); Assert(calls == 0); });
foreach (var mismatch in new (string Name, ForegroundWorkerIdentity Value)[] {
    ("PID zero", b with { Pid = 0 }), ("instance same as donor", b with { InstanceId = a.InstanceId }), ("parent PID", b with { ParentPid = 101 }),
    ("parent birth", b with { ParentCreatedAtTicks = "638000000000000009" }), ("session", b with { SessionId = 2 }),
    ("canonical image path", b with { ExecutablePath = @"C:\Other\qiuya-windows.exe" }), ("image SHA", b with { ImageSHA256 = new string('e', 64) }),
    ("desktop", b with { DesktopSHA256 = new string('f', 64) }), ("architecture", b with { Architecture = "x64" }),
    ("invalid random instance", b with { InstanceId = "forged" }), ("invalid birth", b with { CreatedAtTicks = "0" }), ("unsafe birth syntax", b with { CreatedAtTicks = "6.38e17" })
}) Test("recipient rejects " + mismatch.Name + " before ASFW", () => { var core = Core(); var token = Release(core); var ticket = Prepare(Core(b)) with { Identity = mismatch.Value }; var count = 0; Reject(() => core.Grant(token, mismatch.Value, ticket, () => { }, _ => { count++; return (true, 0); })); Assert(count == 0); });
foreach (var mutate in new (string Name, Func<ForegroundActionTicket, ForegroundActionTicket> Value)[] {
    ("native epoch", t => t with { Epoch = t.Epoch + 1 }), ("logical epoch", t => t with { LogicalEpoch = t.LogicalEpoch + 1 }),
    ("target", t => t with { TargetId = target + "1" }), ("action digest", t => t with { ActionSHA256 = new string('e', 64) }),
    ("geometry digest", t => t with { GeometrySHA256 = new string('f', 64) }), ("surface generation", t => t with { SurfaceGeneration = t.SurfaceGeneration + 1 }),
    ("physical sequence", t => t with { PhysicalSequence = "1" }), ("ticket ID", t => t with { TicketId = new string('7', 32) }),
    ("worker PID", t => t with { Identity = b with { Pid = 301 } }), ("worker birth reused PID", t => t with { Identity = b with { CreatedAtTicks = "638000000000000099" } }),
    ("worker instance", t => t with { Identity = b with { InstanceId = new string('8', 32) } }), ("deadline", t => t with { ExpiresAtQpc = "2200" })
}) Test("act mismatch consumes exact ticket: " + mutate.Name, () => { var core = Core(b); var ticket = Prepare(core); core.BeforeLease(1); Reject(() => core.Consume(mutate.Value(ticket), 1, target, geometry, actionDigest), "foreground-ticket-invalid"); Reject(() => core.Consume(ticket, 1, target, geometry, actionDigest)); });
Test("matching descriptor still refuses different actual action digest", () => { var core = Core(b); var ticket = Prepare(core); core.BeforeLease(1); Reject(() => core.Consume(ticket, 1, target, geometry, new string('e', 64))); });
Test("matching descriptor still refuses changed actual geometry", () => { var core = Core(b); var ticket = Prepare(core); core.BeforeLease(1); Reject(() => core.Consume(ticket, 1, target, new string('e', 64), actionDigest)); });
Test("ticket TTL exactly 2000ms and no renewal", () => { long now = 100; var core = new ForegroundHandoffCore(b, () => now, 1000); var ticket = Prepare(core); Assert(ticket.ExpiresAtQpc == "2100"); now = 2100; Assert(core.Refresh(0, true, true) == "ticket-expired"); Reject(() => core.BeforeLease(1), "foreground-ticket-required"); Assert(core.Controlled); });
Test("TTL only limits act start and does not stop an already consumed original drag", () => { long now = 100; var core = new ForegroundHandoffCore(b, () => now, 1000); var ticket = Prepare(core); core.BeforeLease(1); core.Consume(ticket, 1, target, geometry, actionDigest); now = 9000; Assert(core.Refresh(0, true, true) == null); core.ActionSucceeded(1, target); Assert(core.CleanRelease(1, true) != null); });
Test("release TTL is fixed300s and expired grant never calls API", () => { long now = 100; var core = new ForegroundHandoffCore(a, () => now, 1000); var release = Release(core); Assert(release.ExpiresAtQpc == "300100"); now = 300101; var calls = 0; Reject(() => core.Grant(release, b, Prepare(Core(b)), () => { }, _ => { calls++; return (true, 0); }), "foreground-release-invalid"); Assert(calls == 0); });
Test("idle physical input clears donor even with no active native lease", () => { var core = Core(); var token = Release(core); Assert(core.Refresh(1, true, true) == "physical-input"); Assert(core.Context().Release == null && core.Context().PhysicalSequence == "1"); var calls = 0; Reject(() => core.Grant(token, b, Prepare(Core(b)), () => { }, _ => { calls++; return (true, 0); })); Assert(calls == 0); });
Test("physical input invalidates prepared ticket and leaves receiver controlled", () => { var core = Core(b); var ticket = Prepare(core); Assert(core.Refresh(1, true, true) == "physical-input"); Reject(() => core.BeforeLease(1)); Reject(() => core.Consume(ticket, 1, target, geometry, actionDigest)); Assert(core.Controlled); });
Test("own-window or keyUp sequence changes have the same idle handoff fence", () => { var core = Core(); Release(core); Assert(core.Refresh(1, true, true) == "physical-input"); Assert(core.Refresh(2, true, true) == null); Assert(core.Context().PhysicalSequence == "2"); });
foreach (var scenario in new[] { "monitor-unavailable", "desktop-changed" }) Test(scenario + " invalidates armed tickets and donor", () => { var core = Core(b); Prepare(core); Assert(core.Refresh(0, scenario != "monitor-unavailable", scenario != "desktop-changed") == scenario); Reject(() => core.BeforeLease(1)); Assert(core.Controlled); });
Test("sequence changes during pinned validation abort before ASFW", () => { var core = Core(); var token = Release(core); var ticket = Prepare(Core(b)); var calls = 0; Reject(() => core.Grant(token, b, ticket, () => core.Refresh(1, true, true), _ => { calls++; return (true, 0); }), "foreground-context-changed"); Assert(calls == 0); });
Test("ticket expires while pinned recipient is validated: no ASFW", () => { long now = 100; var core = new ForegroundHandoffCore(a, () => now, 1000); var token = Release(core); var ticket = Prepare(Core(b)); var calls = 0; Reject(() => core.Grant(token, b, ticket, () => now = 2100, _ => { calls++; return (true, 0); }), "foreground-context-changed"); Assert(calls == 0); });
Test("exact ticket cancel cannot cancel another pending ticket or un-gate receiver", () => { var core = Core(b); var ticket = Prepare(core); Assert(!core.Cancel(new string('9', 32))); Assert(core.Cancel(ticket.TicketId)); Assert(!core.Cancel(ticket.TicketId)); Assert(core.Controlled); Reject(() => core.BeforeLease(1)); Reject(() => core.Consume(null, 1, target, geometry, actionDigest)); });
Test("exact release cancel cannot delete another donor token", () => { var core = Core(); var token = Release(core); Assert(!core.CancelRelease(new string('9', 32))); Assert(core.Context().Release == token); Assert(core.CancelRelease(token.TokenId)); Assert(!core.CancelRelease(token.TokenId)); Assert(core.Context().Release == null); });
Test("new action gets a fresh ticket after cancel but may not reuse old ticket", () => { var core = Core(b); var old = Prepare(core); core.Cancel(old.TicketId); var next = Prepare(core, 2); Assert(next.TicketId != old.TicketId); core.BeforeLease(2); core.Consume(next, 2, target, geometry, actionDigest); });
Test("second concurrent prepare cannot replace the exact pending ticket", () => { var core = Core(b); var first = Prepare(core); Reject(() => Prepare(core, 2), "foreground-ticket-pending"); core.BeforeLease(1); core.Consume(first, 1, target, geometry, actionDigest); });
Test("successful action plus failed clean release produces no donor", () => { var core = Core(); core.Refresh(0, true, true); core.BeforeLease(1); core.ActionSucceeded(1, target); Assert(core.CleanRelease(1, false) == null); });
Test("wrong native release epoch produces no donor", () => { var core = Core(); core.Refresh(0, true, true); core.BeforeLease(1); core.ActionSucceeded(1, target); Assert(core.CleanRelease(2, true) == null); });
Test("failed action never becomes donor even after clean release", () => { var core = Core(); core.Refresh(0, true, true); core.BeforeLease(1); core.ActionSucceeded(1, target); core.ActionFailed(); Assert(core.CleanRelease(1, true) == null); });
Test("repeated release cannot issue a second token", () => { var core = Core(); var first = Release(core); Assert(core.CleanRelease(1, true) == null); Assert(core.Context().Release == first); });
Test("physical sequence changes after action completion preclude clean-release donor", () => { var core = Core(); core.Refresh(0, true, true); core.BeforeLease(1); core.ActionSucceeded(1, target); core.Refresh(1, true, true); Assert(core.CleanRelease(1, true) == null); });
Test("physical sequence changes during action preclude donor", () => { var core = Core(); core.Refresh(0, true, true); core.BeforeLease(1); core.Refresh(1, true, true); core.ActionSucceeded(1, target); Assert(core.CleanRelease(1, true) == null); });
Test("new lease destroys obsolete donor context", () => { var core = Core(); Release(core); core.BeforeLease(2); Assert(core.Context().Release == null); });
Test("invalidate does not reopen unticketed receiver activation", () => { var core = Core(b); Prepare(core); core.Invalidate(); Assert(core.Controlled); Reject(() => core.BeforeLease(1)); Reject(() => core.Consume(null, 1, target, geometry, actionDigest)); });
Test("exact old A cancel after B consumes ticket does not touch B state", () => { var donor = Core(); var receiver = Core(b); var token = Release(donor); var ticket = Prepare(receiver); donor.Grant(token, b, ticket, () => { }, _ => (true, 0)); receiver.BeforeLease(1); receiver.Consume(ticket, 1, target, geometry, actionDigest); donor.CancelRelease(token.TokenId); donor.Invalidate(); receiver.ActionSucceeded(1, target); Assert(receiver.CleanRelease(1, true) != null); });
Test("wire round trip keeps identity process birth and sequence exact", () => { var core = Core(b); core.Refresh(9_007_199_254_740_993, true, true); var ticket = core.Prepare(1, 3, target, geometry, actionDigest, 5); var options = new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }; var text = JsonSerializer.Serialize(ticket, options); Assert(text.Contains("\"imageSHA256\"") && text.Contains("\"desktopSHA256\"") && text.Contains("\"physicalSequence\":\"9007199254740993\"")); var decoded = JsonSerializer.Deserialize<ForegroundActionTicket>(text, options); Assert(decoded == ticket); });
Test("configured idle context keeps sequence notifications after donor/ticket consumption", () => { var core = Core(b); core.Refresh(0, true, true); core.Context(); Assert(core.Observing && !core.Armed); Assert(core.Refresh(1, true, true) == "physical-input"); Assert(core.Refresh(2, true, true) == "physical-input"); Assert(core.Refresh(2, true, true) == null); });
Test("capture-only never configured context has no idle event stream", () => { var core = Core(); Assert(!core.Observing); Assert(core.Refresh(1, true, true) == null); Assert(core.Refresh(2, true, true) == null); });
Test("configured monitor or desktop loss emits once per transition rather than100ms flood", () => { var core = Core(); core.Context(); Assert(core.Refresh(0, false, true) == "monitor-unavailable"); Assert(core.Refresh(0, false, true) == null); Assert(core.Refresh(0, true, true) == null); Assert(core.Refresh(0, false, true) == "monitor-unavailable"); core.Refresh(0, true, true); Assert(core.Refresh(0, true, false) == "desktop-changed"); Assert(core.Refresh(0, true, false) == null); });
foreach (var actual in new (string Name, ForegroundWorkerIdentity Value)[] {
    ("PID", b with { Pid = 301 }), ("reused PID birth", b with { CreatedAtTicks = "638000000000000099" }),
    ("parent PID", b with { ParentPid = 101 }), ("parent birth", b with { ParentCreatedAtTicks = "638000000000000099" }),
    ("Session", b with { SessionId = 3 }), ("image bytes SHA", b with { ImageSHA256 = new string('e', 64) }),
    ("canonical image path", b with { ExecutablePath = @"C:\Other\qiuya-windows.exe" })
}) Test("actual pinned OS identity mismatch rejects " + actual.Name, () => { Reject(() => ForegroundHandoffCore.ValidateOsRecipient(b, actual.Value), "foreground-recipient-changed"); var core = Core(); var token = Release(core); var ticket = Prepare(Core(b)); var calls = 0; Reject(() => core.Grant(token, b, ticket, () => ForegroundHandoffCore.ValidateOsRecipient(b, actual.Value), _ => { calls++; return (true, 0); }), "foreground-recipient-changed"); Assert(calls == 0); Reject(() => core.Grant(token, b, ticket, () => { }, _ => { calls++; return (true, 0); })); Assert(calls == 0); });
Test("actual pinned identity accepts exact fields and Windows path case only", () => { ForegroundHandoffCore.ValidateOsRecipient(b, b); ForegroundHandoffCore.ValidateOsRecipient(b, b with { ExecutablePath = b.ExecutablePath.ToLowerInvariant() }); });
Test("logical epoch zero remains compatible while native and surface epochs stay positive", () => { var core = Core(b); core.Refresh(0, true, true); var ticket = core.Prepare(1, 0, target, geometry, actionDigest, 1); Assert(ticket.LogicalEpoch == 0); core.BeforeLease(1); core.Consume(ticket, 1, target, geometry, actionDigest); Reject(() => Core(b).Prepare(0, 0, target, geometry, actionDigest, 1)); Reject(() => Core(b).Prepare(1, -1, target, geometry, actionDigest, 1)); Reject(() => Core(b).Prepare(1, 0, target, geometry, actionDigest, 0)); });
Test("donor after15s and before300s permits one fresh2s ticket without renewal", () => { long now = 100; var donor = new ForegroundHandoffCore(a, () => now, 1000); var receiver = new ForegroundHandoffCore(b, () => now, 1000); var token = Release(donor); now = 16001; Assert(donor.Refresh(0, true, true) == null); Assert(donor.Context().Release == token && token.ExpiresAtQpc == "300100"); var ticket = Prepare(receiver); Assert(ticket.ExpiresAtQpc == "18001"); var calls = 0; var receipt = donor.Grant(token, b, ticket, () => { }, _ => { calls++; return (true, 0); }); Assert(receipt.Allowed && calls == 1); Reject(() => donor.Grant(token, b, ticket, () => { }, _ => { calls++; return (true, 0); })); Assert(calls == 1); });
Test("long-idle donor still rejects physical intervention before fresh ticket", () => { long now = 100; var donor = new ForegroundHandoffCore(a, () => now, 1000); var receiver = new ForegroundHandoffCore(b, () => now, 1000); var token = Release(donor); now = 16001; Assert(donor.Refresh(1, true, true) == "physical-input"); var ticket = Prepare(receiver); var calls = 0; Reject(() => donor.Grant(token, b, ticket, () => { }, _ => { calls++; return (true, 0); })); Assert(calls == 0); });
Test("long-idle donor lost foreground rejects once before API and consumes release", () => { long now = 100; var donor = new ForegroundHandoffCore(a, () => now, 1000); var receiver = new ForegroundHandoffCore(b, () => now, 1000); var token = Release(donor); now = 16001; donor.Refresh(0, true, true); var ticket = Prepare(receiver); var calls = 0; Reject(() => donor.Grant(token, b, ticket, () => throw new NativeFailure("foreground-changed", "Injected lost foreground"), _ => { calls++; return (true, 0); }), "foreground-changed"); Reject(() => donor.Grant(token, b, ticket, () => { }, _ => { calls++; return (true, 0); })); Assert(calls == 0); });
Test("long-idle donor old epoch cannot grant after a new native lease", () => { long now = 100; var donor = new ForegroundHandoffCore(a, () => now, 1000); var receiver = new ForegroundHandoffCore(b, () => now, 1000); var token = Release(donor); now = 16001; donor.Refresh(0, true, true); donor.BeforeLease(2); var ticket = Prepare(receiver); var calls = 0; Reject(() => donor.Grant(token, b, ticket, () => { }, _ => { calls++; return (true, 0); })); Assert(calls == 0); });
Console.WriteLine(JsonSerializer.Serialize(new { kind = "production-foreground-handoff-core-behavior", passed = errors.Count == 0, checks = cases.Count, failed = errors.Count, actualOsInput = false, win32Calls = 0, tests = cases }, new JsonSerializerOptions { WriteIndented = true }));
Environment.ExitCode = errors.Count == 0 ? 0 : 1;

namespace QiuYaTools.Windows { internal sealed class NativeFailure(string code, string message) : Exception(message) { internal string Code { get; } = code; } }
